# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">HZ. MUHAMMED\'İN (SAV) RİSALETİ: İLK VAHİY VE FETRET-İ VAHİY</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">HİRA NUR DAĞI VE İLK VAHİY (610 RAMAZAN)</text>\n  <text x="35" y="88" font-size="11.2" fill="#1e3a8a">• Mekân ve Zaman: Hira Mağarası, 610 yılı Ramazan ayı</text>\n  <text x="35" y="108" font-size="11.2" fill="#1e3a8a">• Vahiy Meleği Cebrail (as) ve İlk Emir: Alak 1-5</text>\n  <text x="35" y="126" font-size="11.2" font-weight="bold" fill="#1e40af">  «Yaratan Rabbinin adıyla oku! (İkra\' bismi Rabbike...)»</text>\n  <text x="35" y="148" font-size="11.2" fill="#1e3a8a">• Hz. Hatice\'nin (ra) Tesellisi: «Allah seni mahcup etmez;</text>\n  <text x="35" y="166" font-size="11.2" fill="#1e3a8a">  sen akrabanı gözetir, mazluma yardım edersin.»</text>\n  <text x="35" y="186" font-size="11.2" fill="#1e3a8a">• Varaka bin Nevfel: «Bu gelen Musa\'ya inen Nâmûs\'tur.»</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">FETRET-İ VAHİY VE TEBLİĞ EMRİNİN BAŞLAMASI</text>\n  <text x="370" y="88" font-size="11.2" fill="#14532d">• Fetret-i Vahiy: İlk vahiyden sonra vahyin bir süre</text>\n  <text x="370" y="106" font-size="11.2" fill="#14532d">  kesilmesi (ruhen yeni vahiylere hazırlık dönemi)</text>\n  <text x="370" y="128" font-size="11.2" fill="#14532d">• İkinci Vahiy ve Tebliğ Emri: Müddessir Suresi 1-7</text>\n  <text x="370" y="146" font-size="11.2" font-weight="bold" fill="#166534">  «Ey örtünüp bürünen! Kalk ve uyar! Rabbini yücelt!»</text>\n  <text x="370" y="168" font-size="11.2" fill="#14532d">• Nebi (vahiy alan) konumundan Resul (tebliğle</text>\n  <text x="370" y="186" font-size="11.2" fill="#14532d">  görevli elçi) sorumluluğuna geçiş</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Alak 1-5 ile nübüvvet (peygamberlik), Müddessir 1-7 ile risalet/tebliğ (uyarma görevi) başlamıştır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">İLK MÜSLÜMANLAR (SÂBİKÛN-İ EVVELÛN) VE DÂRÜ\'L-ERKAM</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#854d0e">İSLAM\'A İLK GİREN DÖRT ÖNCÜ ŞAHSİYET</text>\n  <text x="35" y="88" font-size="11.2" fill="#713f12">• 1. İlk Kadın: Hz. Hatice bint Huveylid (ra)</text>\n  <text x="35" y="110" font-size="11.2" fill="#713f12">• 2. Çocuk/Genç: Hz. Ali bin Ebî Tâlib (ra)</text>\n  <text x="35" y="132" font-size="11.2" fill="#713f12">• 3. Azatlı Köle / Evlatlık: Hz. Zeyd bin Hârise (ra)</text>\n  <text x="35" y="154" font-size="11.2" fill="#713f12">• 4. Hür Erkek / Yakın Dost: Hz. Ebû Bekir (ra)</text>\n  <text x="35" y="176" font-size="11.2" font-weight="bold" fill="#854d0e">• Sâbikûn-i Evvelûn: İslam\'da öne geçen ilk müminler</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">EĞİTİM VE TEBLİĞ MERKEZİ: DÂRÜ\'L-ERKAM</text>\n  <text x="370" y="88" font-size="11.2" fill="#581c87">• Sahibi: Genç sahabi Erkam bin Ebü\'l-Erkam (ra)</text>\n  <text x="370" y="110" font-size="11.2" fill="#581c87">• Konumu: Safâ Tepesi eteklerinde, Kâbe\'ye yakın</text>\n  <text x="370" y="132" font-size="11.2" fill="#581c87">• İşlevi: İslam tarihinin ilk eğitim, irşat ve tebliğ</text>\n  <text x="370" y="150" font-size="11.2" fill="#581c87">  merkezi (Kur\'an tilaveti, namaz ve kardeşlik eğitimi)</text>\n  <text x="370" y="172" font-size="11.2" fill="#581c87">• Hz. Ömer\'in (ra) İslam\'a girişine kadar merkez oldu.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">İlk dört Müslüman; kadın, genç, hür erkek ve azatlı köle kesimlerini temsil ederek İslam\'ın evrenselliğini gösterir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">GİZLİ DAVET VE AÇIK DAVET SÜREÇLERİNİN MUKAYESESİ (SYR.10.2.1)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">1. GİZLİ (FERDÎ) DAVET DÖNEMİ (610 - 613)</text>\n  <text x="35" y="88" font-size="11.2" fill="#7c2d12">• Süre ve Dayanak: 3 Yıl — Müddessir Suresi 1-7</text>\n  <text x="35" y="108" font-size="11.2" fill="#7c2d12">• Yöntem: Aile ve güvenilir dostlara birebir davet</text>\n  <text x="35" y="128" font-size="11.2" fill="#7c2d12">• Amaç: Müşriklerin ani saldırısını önlemek ve</text>\n  <text x="35" y="146" font-size="11.2" fill="#7c2d12">  inancı sağlam çekirdek kadroyu (yaklaşık 40 kişi) kurmak</text>\n  <text x="35" y="168" font-size="11.2" fill="#7c2d12">• Müşrik Tepkisi: Henüz alay ve kayıtsızlık düzeyinde</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#ecfeff" stroke="#0891b2" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#155e75">2. AÇIK (UMUMİ) DAVET DÖNEMİ (613 - 622)</text>\n  <text x="370" y="88" font-size="11.2" fill="#164e63">• Süre ve Dayanak: 9-10 Yıl — Şuarâ 214 ve Hicr 94</text>\n  <text x="370" y="108" font-size="11.2" fill="#164e63">• Yöntem: Safâ Tepesi konuşması, panayırlar ve Kâbe</text>\n  <text x="370" y="128" font-size="11.2" fill="#164e63">• Amaç: İlahi mesajı tüm Mekke toplumuna ve dışarıdan</text>\n  <text x="370" y="146" font-size="11.2" fill="#164e63">  gelen kabilelere açıktan ilan etmek</text>\n  <text x="370" y="168" font-size="11.2" fill="#164e63">• Müşrik Tepkisi: Alay, iftira, işkence ve 3 yıllık boykot</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Ortak Yön: Her iki dönemde de temel mesaj Tevhit, Ahiret ve Ahlak olup şiddete asla başvurulmamıştır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
